package br.com.social.post;import br.com.social.post.dto.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/posts") public class PostController{private final PostService service;public PostController(PostService s){service=s;}@GetMapping public List<PostService.View> feed(Authentication a){return service.feed(a.getName());}@GetMapping("/mine") public List<PostService.View> mine(Authentication a){return service.mine(a.getName());}@GetMapping("/admin") @PreAuthorize("hasRole('ADMIN')") public List<PostService.View> admin(Authentication a){return service.admin(a.getName());}@PostMapping @ResponseStatus(HttpStatus.CREATED) public Post create(@Valid @RequestBody PostRequest q,Authentication a){return service.create(q.content(),a.getName());}@PostMapping("/{id}/like") public Map<String,Boolean> like(@PathVariable Long id,Authentication a){return Map.of("liked",service.toggleLike(id,a.getName()));}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id,Authentication a){boolean admin=a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMIN"));service.delete(id,a.getName(),admin);}@PatchMapping("/{id}/hidden") @PreAuthorize("hasRole('ADMIN')") public Post hidden(@PathVariable Long id,@RequestBody Map<String,Boolean> body){return service.moderate(id,Boolean.TRUE.equals(body.get("hidden")));}}
